      <img class="file-upload-image" src="#" alt="your image" />
      <div class="image-title-wrap">
        <label>Edit File Name</label>
        <input type="text" class="filename" placeholder="optional" />
      </div>
      <button type="button" class="remove-image">Remove</button>
    </div>
    <div class="file-upload-error">Please select a valid image file</div>
  </div>

  <script>
    function readURL(input) {
      if (input.files && input.files[0]) {
        var reader = new FileReader();
        reader.onload = function(e) {
          $('.file-upload-image').attr('src', e.target.result);
          $('.file-upload-content').show();
          $('.image-title-wrap').html("Edit File Name" + "<br/><input type='text' class='filename' placeholder='optional'/>");
          $('.image-upload-wrap').hide();
        }
        reader.addEventListener('load', function() {
          // This is used to display the image after reading
        }, false);
        reader.readAsDataURL(input.files[0]);
      } else {
        removeUpload();
      }
    }

    function removeUpload() {
      $('.file-upload-content').hide();
      $('.image-upload-wrap').show();
    }

    $('.image-upload-wrap').bind('dragover', function () {
      $('.image-upload-wrap').addClass('image-dropping');
    });
    $('.image-upload-wrap').bind('dragleave', function () {
      $('.image-upload-wrap').removeClass('image-dropping');
    });

    $('.file-upload-input').on('change', function() {
      var file = this.files[0];
      if (file.size > 5 * 1024 * 1024) {
        $('.file-upload-error').html('File size exceeds 5MB').addClass('active');
        return;
      }
      var validImageTypes = ['image/jpeg', 'image/png', 'image/gif'];
      if (validImageTypes.indexOf(file.type) === -1) {
        $('.file-upload-error').html('Please select a valid image file').addClass('active');
        return;
      }
      $('.file-upload-error').removeClass('active');
      readURL(this);
    });
  </script>
</body>
</html>


